ts-prim-001.example:
```ts
let lower: string = 'hello';   // ✅ the primitive — what you want
console.log(lower.toUpperCase());

function shout(s: string) { return s.toUpperCase(); }
const wrapped: String = new String('hi'); // the wrapper OBJECT type
// @ts-expect-error a String object is not assignable to the string primitive
shout(wrapped);
```

ts-prim-002.example:
```ts
const a: string = 'hi';
const b: number = 42;     // ints and floats are both `number`
const c: boolean = true;

// The type name matches what typeof reports:
console.log(typeof a, typeof b, typeof c); // 'string' 'number' 'boolean'
```

ts-prim-003.example:
```ts
let myName = 'Alice'; // inferred as string — no annotation needed
console.log(myName.toUpperCase());

// @ts-expect-error number is not assignable to the inferred type string
myName = 42;

const exact = 'Alice'; // const infers the literal type "Alice"
const widened = exact; // still "Alice" here
console.log(exact, widened);
```

ts-prim-mcq-001.example:
```ts
let value: any = 'hello';
value.foo.bar();      // no error — any disables all checking
value = 42;
value();              // calling a number — still no compile error
const n: number = value; // any flows into any type unchecked

// Safer alternative: unknown forces you to narrow first.
let u: unknown = 'hi';
// @ts-expect-error 'u' is of type 'unknown' — must narrow before use
u.toUpperCase();
if (typeof u === 'string') u.toUpperCase(); // ok
console.log(n);
```

ts-prim-004.example:
```ts
// Explicit types satisfy noImplicitAny:
function double(x: number) { return x * 2; }

// @ts-expect-error noImplicitAny: parameter 'x' implicitly has an 'any' type
function echo(x) { return x; }

console.log(double(2), echo('still works at runtime'));
```

ts-prim-mcq-002.example:
```ts
const req = { method: 'GET' };
const m: string = req.method; // inferred type is string (widened, mutable prop)

// @ts-expect-error string is not assignable to the literal type "GET"
const lit: 'GET' = req.method;
