```

ts-prim-005.example:
```ts
const req = { method: 'GET' } as const;
const m: 'GET' = req.method; // literal "GET", thanks to as const

// @ts-expect-error cannot assign to 'method' — it is a read-only property
req.method = 'POST';
console.log(m);
```

ts-prim-mcq-003.example:
```ts
function printText(s: string, alignment: 'left' | 'right' | 'center') {}

let a = 'left'; // widened to string
// @ts-expect-error string is not assignable to the literal union
printText('Hello', a);

const b = 'left'; // inferred as the literal "left"
printText('Hello', b);          // ✅ ok
printText('Hello', a as 'left'); // ✅ also ok via assertion
```

ts-prim-006.example:
```ts
function printLen(x: string | null) {
  // @ts-expect-error 'x' is possibly 'null' (strictNullChecks on)
  console.log(x.length);

  if (x !== null) console.log(x.length); // ✅ narrowed to string
  console.log(x?.length ?? 0);           // ✅ optional chaining + default
}
printLen('hello');
```

ts-prim-mcq-004.example:
```ts
function liveDangerously(x?: number | null) {
  // `!` removes null/undefined from the type at COMPILE time only.
  console.log(x!.toFixed()); // crashes at runtime if x really is null/undefined
}
liveDangerously(42); // fine
// liveDangerously() — would throw at runtime despite compiling cleanly
```

ts-prim-007.example:
```ts
const big1: bigint = BigInt(100);
const big2 = 100n;            // literal form
console.log(big1 === big2);   // true — same numeric value

const s1: symbol = Symbol('id');
const s2: symbol = Symbol('id');
console.log(s1 === s2);       // false — every Symbol() is unique
console.log(Symbol.for('k') === Symbol.for('k')); // true — shared registry
```

