ts-arr-mcq-001.example:
```ts
function doStuff(values: ReadonlyArray<string>) {
  const copy = values.slice();   // A: ok (returns a new array)
  console.log(values[0]);        // B: ok (read by index)
  // @ts-expect-error 'push' does not exist on a readonly array
  values.push('hello!');         // C: error
  return values.length;          // D: ok (read)
}
doStuff(['a', 'b']);
```

