ts-tuple-mcq-001.example:
```ts
function doSomething(pair: readonly [string, number]) {
  console.log(pair[0], pair[1]); // reads are fine
  // @ts-expect-error cannot assign to '0' — it is a read-only property
  pair[0] = 'hello!';
}
doSomething(['a', 1]);
```

ts-obj-001.example:
```ts
interface PaintOptions { shape: string; xPos?: number; yPos?: number; }

function paint(opts: PaintOptions) {
  // @ts-expect-error 'opts.xPos' is possibly 'undefined'
  const x: number = opts.xPos;
  const safeX = opts.xPos ?? 0; // provide a default
  return safeX;
}
paint({ shape: 'circle' });        // xPos omitted — allowed
paint({ shape: 'square', xPos: 10 });
```

ts-obj-002.example:
```ts
