ts-obj-mcq-001.example:
```ts
interface SquareConfig { color?: string; width?: number; }
function createSquare(config: SquareConfig) { return config; }

// @ts-expect-error 'colour' is not a known property (excess property check on a literal)
createSquare({ colour: 'red', width: 100 });

createSquare({ color: 'red', width: 100 }); // ✅ correct key
const opts = { colour: 'red', width: 100 };
createSquare(opts); // ✅ via a variable, excess checks don't apply
```

ts-obj-004.example:
```ts
interface Colorful { color: string }
interface Circle { radius: number }

interface ColorfulCircle extends Colorful, Circle {} // inheritance
const a: ColorfulCircle = { color: 'red', radius: 1 };
type CC = Colorful & Circle;                          // intersection
const b: CC = { color: 'blue', radius: 2 };

interface A { id: string }
interface B { id: number }
// @ts-expect-error extends with conflicting 'id' is a declaration error
interface Bad extends A, B {}
type Inter = A & B; // compiles, but Inter['id'] is `never` (string & number)
console.log(a, b);
```

ts-rec-001.example:
```ts
type CatName = 'miffy' | 'boris' | 'mordred';
interface CatInfo { age: number; breed: string }

// Must include every CatName key, each a CatInfo:
const cats: Record<CatName, CatInfo> = {
  miffy: { age: 10, breed: 'Persian' },
  boris: { age: 5, breed: 'Maine Coon' },
  mordred: { age: 16, breed: 'British Shorthair' },
};
console.log(cats.boris.age);
```
